    """
    Dynamically create a Point subclass.
    """
    class _Point(Point):
        def __new__(cls, *args):
            if len(args) < 2:
                raise ValueError("Point requires at least 2 arguments")
            return Point.__new__(cls, *args)

        def __init__(self, *args):
            if len(args) > 2:
                raise ValueError("Point requires at most 2 arguments")
            if not isinstance(args[0], (SupportedCRS, str)):
                raise ValueError("Invalid first argument, must be a CRS or string")
            if len(args) == 2 and not isinstance(args[1], (SupportedCRS, CoordinateTuple)):
                raise ValueError("Invalid second argument, must be a CRS or CoordinateTuple")

            crs, coordinate = args[0], args[1]
            if isinstance(crs, str):
                crs = srid_map[crs]
            elif not isinstance(crs, SupportedCRS):
                raise ValueError("Invalid first argument, must be a CRS or string")

            if isinstance(coordinate, tuple) and len(coordinate) == 2:
                coordinate = CoordinateTuple(*coordinate)

            if not isinstance(coordinate, CoordinateTuple):
                raise ValueError("Invalid second argument, must be a CRS or CoordinateTuple")

            self._crs = crs
            self._coordinate = coordinate

