def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    Args:
        cache (callable): A callable that returns a cache object.
        key (callable, optional): A callable that returns a cache key. Defaults to hashkey.
        lock (callable, optional): A callable that returns a lock object. Defaults to None.
    """

    def decorator(method):
        def wrapper(*args, **kwargs):
            c = cache(*args, **kwargs)
            if c is None:
                return method(*args, **kwargs)
            k = key(*args, **kwargs)
            try:
                return c[k]
            except KeyError:
                pass  # key not found
            v = method(*args, **kwargs)
            try:
                c[k] = v
            except ValueError:
                pass  # value too large
            return v
        return wrapper
    return decorator

