def patched_normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if isinstance(sequence, (Declaration, tuple)):
        output.append(sequence)
    elif isinstance(sequence, type) and (
        InterfaceClass in sequence.__mro__ or
        zope.interface.declarations.Implements in sequence.__mro__):
        output.append(sequence)
    elif isinstance(sequence, Iterable):
        for v in sequence:
            patched_normalizeargs(v, output)
    return output

