def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re
    from types import ModuleType
    from typing import List, Dict

    valid_label_regex = re.compile(r"^([a-zA-Z][a-zA-Z0-9_]+)$")
    valid_string_regex = re.compile(r"^[a-zA-Z0-9_$@%#*.,:;+=/-]+$")

    def _is_valid_key(key):
        return (
            (isinstance(key, (str, ModuleType)) and valid_label_regex.match(key))
            or (isinstance(key, (int, float)) and not isinstance(key, bool))
        )

    def _is_valid_value(value):
        return (
            (isinstance(value, (str, ModuleType)) and valid_string_regex.match(value))
            or (isinstance(value, (int, float)) and not isinstance(value, bool))
        )

    def _is_valid_label(label):
        if not _is_valid_key(label):
            return False
        else:
            return _is_valid_value(label)

    def _validate_label_key(key, labels):
        if not _is_valid_key(key):
            raise ValidationError(
                f"The label key '{key}' does not match the regular expression"
                f" '{valid_label_regex.pattern}'"
            )

        if isinstance(key, str) and key in labels:
            raise ValidationError(
                f"The label key '{key}' is already in use by another label"
            )

    def _validate_label_value(value, labels):
        if not _is_valid_value(value):
            raise ValidationError(
                f"The label value '{value}' does not match the regular expression"
                f" '{valid_string_regex.pattern}'"
            )

        for label_key in labels:
            if (
                label_key != value
                and isinstance(labels[label_key], str)
                and labels[label_key] == value
            ):
                raise ValidationError(
                    f"The label value '{value}' is already in use by the label key"
                    f" '{label_key}'"
                )

    messages = []
    for label_key in labels:
        if isinstance(label_key, str):
            _validate_label_key(label_key, labels)
            _validate_label_value(labels[label_key], labels)
        else:
            messages.append(
                {"['invalid']": 'expected string or bytes-like object'}
            )

    for label_value in labels.values():
        if isinstance(label_value, (int, float, bool)):
            if not _is_valid_value(label_value):
                messages.append(
                    {str(label_value): 'expected string or bytes-like object'}
                )
    return messages

