        if isinstance(value, dict) and not isinstance(value, (list, tuple)):
            new_dict[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            if not first_level:
                new_dict[key] = [generate_default_observer_schema_dict(item) for item in value]
            else:
                new_dict[key] = [item for item in value]
        else:
            if key in IDENTIFYING_FIELDS:
                new_dict[key] = value
