def check_digests_present_and_used(manifest_files, digests_used):
    """
    Check all digests in manifest that are needed are present and used.

    :param manifest_files: List of files in manifest to check
    :param digests_used: Set of used digests
    """

    # Check that all needed digests are present
    for manifest_file in manifest_files:
        needed_digests = manifest_file.get("Needed", [])
        if not set(needed_digests).issubset(digests_used):
            raise ValueError(f"Missing digests in manifest: {needed_digests - digests_used}")

    # Check that all used digests are present in manifest
    for digest in digests_used:
        if digest not in manifest_files:
            raise ValueError(f"Used digest not in manifest: {digest}")

    # Check that all used digests are used in exactly one of the manifest files
    for digest, count in collections.Counter(digests_used).items():
        if count > 1:
            raise ValueError(f"Digest used in multiple manifest files: {digest}")

