def get_version_file_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    :param inventory: Inventory of all versions in state
    :type inventory: dict
    :param version: Version in inventory to get file map for
    :type version: str
    :return: Dictionary of logical path -> set of files
    :rtype: dict
    """

    version_files = inventory[version]
    logical_path_map = {}

    for version_file in version_files:
        filename = version_file.split("/")[-1]
        logical_path = filename.split("__")[0]
        if logical_path in logical_path_map:
            logical_path_map[logical_path].add(filename)
        else:
