def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if sys.platform == 'win32':
            platform = 0
        else:
            platform = 1

    if platform == 0:  # Windows/CMD
        pattern = r'[^"^']+|"([^"\\]*(\\.[^"\\]*)*)"|' \
                  r"'([^'\\]*(\\.[^'\\]*)*)'"
    else:  # POSIX
        pattern = r'[^"\\, ]+|"([^"\\]*(\\.[^"\\]*)*)"|' \
                  r"'([^'\\]*(\\.[^'\\]*)*)'|'[^']+'"
    return re.findall(pattern, s)

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    pattern = r"(\d+)\s*([a-zA-Z]+)"
    match = re.match(pattern, frequency)
    if not match:
        raise ValueError(f"Invalid frequency: {frequency}")

    quantity = int(match.group(1))
    unit = match.group(2).lower()

    if unit == "week":
        return datetime.timedelta(weeks=quantity)
    elif unit == "day":
        return datetime.timedelta(days=quantity)
    elif unit == "hour":
        return datetime.timedelta(hours=quantity)
    elif unit == "minute":
        return datetime.timedelta(minutes=quantity)
    else:
        raise ValueError(f"Invalid unit of time: {unit}")

