import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not isinstance(commands, list):
        commands = [commands]

    if verbose:
        print(f"Running command:\n{' '.join(commands)}")

    try:
        p = subprocess.Popen(commands, cwd=cwd, env=env)
    except FileNotFoundError:
        return subprocess.CalledProcessError(returncode=-2, cmd=commands)

    wait_stdout = None
    wait_stderr = None

    if p.stdout:
        wait_stdout = sys.stdout.attach(p.stdout, read_line=args.read_line)
    if p.stderr:
        wait_stderr = sys.stderr.attach(p.stderr)

    original_wait = p.wait
    def wait():
        original_wait()

        if wait_stdout:
            wait_stdout()
        if wait_stderr:
            wait_stderr()

    p.wait = wait

    return p
