def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    config_dict = {}
    log_records = []

    for config_filename in config_filenames:
        try:
            # Load and parse the configuration file
            with open(config_filename) as f:
                # Replace environment variables in the config if necessary
                if resolve_env:
                    content = f.read().replace(os.linesep, '')
                    config = eval(content, {}, {**os.environ})
                else:
                    config = yaml.safe_load(f)

                # Validate the configuration
                if not isinstance(config, collections.abc.Mapping):
                    raise ValueError(f"Invalid configuration file: '{config_filename}'. Expected a mapping, got {type(config)}.")

                # Override any provided overrides
                if overrides:
                    config = {**config, **overrides}

                # Add the configuration to the result dict
                config_dict[config_filename] = config
        except (IOError, yaml.YAMLError, ValueError) as e:
            log_records.append(logging.makeLogRecord({
                'name': 'load_configurations',
                'level': logging.ERROR,
                'pathname': config_filename,
                'msg': f"Error parsing configuration file '{config_filename}': {e}"
            }))

    return config_dict, log_records

