def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    output = []
    in_code_block = False
    for line in text.splitlines():
        if "```" in line:
            in_code_block = not in_code_block
            continue
        if in_code_block:
            output.append(line)
            continue
        for tag in re.findall(r"\B#\w+", line):
            tags.add(tag[1:])
            if replacer is not None:
                output.append(replacer(tag[1:]))
            else:
                output.append(tag)
    return tags, "\n".join(output)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links.

    :param text: The text to process.
    """
    # Use regular expressions to find all the links in the text
    url_regex = r"((http|ftp)s?://|www\.)\S+"
    url_pattern = re.compile(url_regex)

    # Replace all the URLs with hyperlinks
    def url_to_link(url):
        if url.startswith("www."):
            url = "http://" + url
        return '<a href="{}">{}</a>'.format(url, url)

    text = re.sub(url_pattern, url_to_link, text)

    # Add some additional attributes to the links we've found
    def add_attrs(match):
        # Only add the attributes if the link is not inside an anchor tag
        if not match.group(1).startswith("<a"):
            return (
                '<a href="{}"'.format(match.group(0))
                + ' target="_blank" rel="noopener noreferrer"'
                + '>{}</a>'.format(match.group(0))
            )
        else:
            return match.group(0)

    text = re.sub(url_pattern, add_attrs, text)
    return text

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if not scheme in ('http', 'https', 'ftp', 'ftps'):
        return None
    try:
        req = Urllib2HeadRequest(url, headers={'Host': netloc})
        resp = urlopen(req)
        if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
            return None
        return resp.info().get('content-type', None)
    except URLError as e:
        pass
    finally:
        if resp is not None:
            resp.close()

