def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        # if the argument has a default value set, use it
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # if the argument is a SpecOption, try to resolve its value from the spec
        if isinstance(arg, SpecOption):
            # if the argument has a default value set in its spec, use it
            if not isinstance(arg.spec.default, Unspecified):
                defaults[arg.name] = arg.spec.default

            # if the argument spec has a none-default value, override the default
            # value if the user has not provided it
            elif arg.spec.value is not None:
                defaults[arg.name] = arg.spec.value

    return defaults

